template <class T>
static void siftDown(std::vector<T>& a, int lo, int hi) {
    int root = lo;
    while (2 * root + 1 < hi) {
        int child = 2 * root + 1;
        if (child + 1 < hi && a[child] < a[child + 1]) ++child;
        if (a[root] < a[child]) { std::swap(a[root], a[child]); root = child; }
