from collections import deque

def topo_order(graph):
    indeg = {n: 0 for n in graph}
    for n in graph:
        for m in graph[n]:
            indeg[m] += 1
    q = deque(n for n in indeg if indeg[n] == 0)
    out = []
    while q:
        n = q.popleft()
        out.append(n)
        for m in graph[n]:
            indeg[m] -= 1
            if indeg[m] == 0:
                q.append(m)
    if len(out) != len(graph):
        raise ValueError("cycle detected")
    return out
