```python
def sort_fast(data, key=None):
    if not data:
        return []
    if key is None and all(isinstance(x, int) and x >= 0 for x in data):
        return _counting_sort(data)
    return sorted(data, key=key)

def _counting_sort(nums):
    if not nums:
        return []
    hi = max(nums)
    counts = [0] * (hi + 1)
    for n in nums:
        counts[n] += 1
    out = []
    for value, c in enumerate(counts):
        if c:
            out.extend([value] * c)
    return out
